using FallenForest.Core;using FallenForest.Player;using UnityEngine;namespace FallenForest.UI{public sealed class DeathMenuController:MonoBehaviour{[SerializeField]private GameObject panel;[SerializeField]private PlayerMotor player;[SerializeField]private CameraMotion cameraMotion;[SerializeField]private CanvasGroup blackout;private void Awake(){if(panel!=null)panel.SetActive(false);}public void Show(){if(panel!=null)panel.SetActive(true);}public void Continue(){if(player==null)player=FindFirstObjectByType<PlayerMotor>();if(cameraMotion==null)cameraMotion=FindFirstObjectByType<CameraMotion>();if(SaveSystem.TryLoad(out int docs,out bool boiled,out Vector3 pos)){GameProgress.Instance?.Restore(docs,boiled);player?.Teleport(pos);}if(blackout!=null)blackout.alpha=0;if(panel!=null)panel.SetActive(false);cameraMotion?.ClearCinematicFov();cameraMotion?.SetInputEnabled(true);player?.SetControlsEnabled(true);}public void MainMenu()=>SceneFlow.MainMenu();}}
